 elseif kind=='modes'then add('t','HIDE UNUSED MODES','hideModes');for _,md in ipairs(modeDefs)do local found=false;for _,d in ipairs(modes)do if d.id==md.id and d.finish>d.start then found=true break end end;if found or not hideModes then add('s',md.name,'modeSection:'..md.id);for i,d in ipairs(modes)do if d.id==md.id and d.finish>d.start then add('h','RANGE '..i,'mode:'..i..':header');add('r','Range [us]','mode:'..i..':range')end end end end
