 elseif kind=='beeper'then add('s','ANALOG BEEPER');for i,n in ipairs(beepNames)do add('t',n,'beep:'..(i-1))end;add('s','DSHOT BEACON');add('n','Beacon Tone','tone',1,5);for i=1,5 do add('t','Beacon Condition '..i,'dbeep:'..(i-1))end
