local function readProfiles()pApis.status=rf2.useApi('mspStatus');pApis.tune=rf2.useApi('mspPidTuning');pApis.ctrl=rf2.useApi('mspPidProfile');pApis.rescue=rf2.useApi('mspRescueProfile');pApis.gov=rf2.useApi('mspGovernorProfile');pTune=pApis.tune.getDefaults();pCtrl=pApis.ctrl.getDefaults();pRescue=pApis.rescue.getDefaults();pGov=pApis.gov.getDefaults();local n=5;local function pd()n=n-1;if n==0 then busy=false;state='PROFILE #'..(prof.current+1)..' / LIVE';build()end end;pApis.status.getStatus(function(_,x)prof.current=x.profile or 0;pd()end,nil);pApis.tune.read(function(_,x)pTune=x;pd()end,nil,pTune);pApis.ctrl.read(function(_,x)pCtrl=x;pd()end,nil,pCtrl);pApis.rescue.read(function(_,x)pRescue=x;pd()end,nil,pRescue);pApis.gov.read(function(_,x)pGov=x;pd()end,nil,pGov)end
