local function readRates()rateApi=rateApi or rf2.useApi('mspRcTuning');pApis.status=pApis.status or rf2.useApi('mspStatus');rateData=rateApi.getDefaults();local pending=2;local function done()pending=pending-1;if pending==0 then state='RATE PROFILE #'..(rprof.current+1)..' / LIVE';busy=false;build()end end;pApis.status.getStatus(function(_,x)rprof.current=x.rateProfile or 0;done()end,nil);rateApi.read(function(_,d)rateData=d;done()end,nil,rateData)end
local function selectRateProfile(v)if v==rprof.current then return end;busy=true;state='CHANGING RATE PROFILE...';rf2.mspQueue:add({command=210,payload={128+v},processReply=function()rprof.current=v;readRates()end,errorHandler=function()busy=false;state='RATE PROFILE CHANGE ERROR'end})end
local function readModes()local pending=4;modes={};modeDefs={};modeNames={};local extra={},{};local names,ids={},{};local function done()pending=pending-1;if pending==0 then for i,d in ipairs(modes)do local e=extra[i]or{};d.logic=e.logic or 0;d.linked=e.linked or 0 end;for i,id in ipairs(ids)do local name=names[i]or('MODE '..id);modeDefs[#modeDefs+1]={id=id,name=name};modeNames[id]=name end;modesOriginal=cloneRecords(modes);state='CONNECTED / READ ONLY';busy=false;build()end end;rf2.mspQueue:add({command=34,processReply=function(_,b)b.offset=1;while b.offset+3<=#b do modes[#modes+1]={id=u8(b),aux=u8(b),start=1500+s8(u8(b))*5,finish=1500+s8(u8(b))*5}end;done()end,errorHandler=done});rf2.mspQueue:add({command=238,processReply=function(_,b)b.offset=1;local n=u8(b);for i=1,n do extra[i]={id=u8(b),logic=u8(b),linked=u8(b)}end;done()end,errorHandler=done});rf2.mspQueue:add({command=116,processReply=function(_,b)b.offset=1;local q='';while b.offset<=#b do local c=u8(b);if c==59 then names[#names+1]=q;q=''elseif c>0 then q=q..string.char(c)end end;if q~=''then names[#names+1]=q end;done()end,errorHandler=done});rf2.mspQueue:add({command=119,processReply=function(_,b)b.offset=1;while b.offset<=#b do ids[#ids+1]=u8(b)end;done()end,errorHandler=done})end
local function parseAdjustment(b)local d={func=u8(b),ena=u8(b),es=1500+s8(u8(b))*5,ee=1500+s8(u8(b))*5,aux=u8(b),r1s=1500+s8(u8(b))*5,r1e=1500+s8(u8(b))*5,r2s=1500+s8(u8(b))*5,r2e=1500+s8(u8(b))*5,min=u16(b),max=u16(b),step=u8(b)};if d.min>=32768 then d.min=d.min-65536 end;if d.max>=32768 then d.max=d.max-65536 end;return d end;local function readAdjust()adjusts={};adjustsOriginal={};adjApiVersion=0;local apiDone=false;local slotsDone=false;local failed=false;local function finish()if not apiDone or not slotsDone then return end;adjustsOriginal=cloneRecords(adjusts);busy=false;state=failed and'ADJUSTMENTS READ / PARTIAL ERROR'or('FC API '..string.format('%.2f',adjApiVersion)..' / '..#adjusts..' SLOTS');build()end;rf2.mspQueue:add({command=1,processReply=function(_,b)local ok=pcall(function()if #b>=3 then adjApiVersion=(b[2]or 0)+(b[3]or 0)/100 end end);if not ok then failed=true end;apiDone=true;finish()end,errorHandler=function()failed=true;apiDone=true;finish()end});rf2.mspQueue:add({command=167,processReply=function(_,b)local count=#b;if count<1 then failed=true;slotsDone=true;finish();return end;local remaining=count;for index=0,count-1 do local slot=index;rf2.mspQueue:add({command=156,payload={slot},processReply=function(_,q)local ok=pcall(function()if #q~=14 then error('bad adjustment length')end;q.offset=1;adjusts[slot+1]=parseAdjustment(q)end);if not ok then failed=true end;remaining=remaining-1;if remaining<=0 then slotsDone=true;finish()end end,errorHandler=function()failed=true;remaining=remaining-1;if remaining<=0 then slotsDone=true;finish()end end})end end,errorHandler=function()failed=true;slotsDone=true;finish()end})end;local function readSimple(cmd,cb)rf2.mspQueue:add({command=cmd,processReply=function(_,b)b.offset=1;cb(b);state='CONNECTED';busy=false;build()end,errorHandler=function()busy=false;state='READ ERROR'end})end
local function read()if busy then return end;busy=true;state='READING FC...';if kind=='profiles'then readProfiles()elseif kind=='rates'then readRates()elseif kind=='modes'then readModes()elseif kind=='adjustments'then readAdjust()elseif kind=='beeper'then readSimple(184,function(b)beep.mask=u32(b);beep.tone=u8(b);beep.dmask=u32(b)end)elseif kind=='blackbox'then local pending=2;local function bd()pending=pending-1;if pending==0 then state='CONNECTED';busy=false;build()end end;rf2.mspQueue:add({command=80,processReply=function(_,b)b.offset=1;black.supported=u8(b);black.device=u8(b);black.mode=u8(b);black.denom=u16(b);black.fields=u32(b);if b.offset<=#b then black.erase=u16(b);black.rolling=u8(b);black.grace=u8(b)end;bd()end,errorHandler=bd});rf2.mspQueue:add({command=70,processReply=function(_,b)b.offset=1;local flags=u8(b);flash.ready=bit32.btest(flags,1);flash.supported=bit32.btest(flags,2);flash.sectors=u32(b);flash.total=u32(b);flash.used=u32(b);bd()end,errorHandler=bd})else busy=false;state='LIVE';build()end end
local function writeRates()rateApi.write(rateData)end
local function modePayload(i,d)local q={i-1,d.id,d.aux,math.floor((d.start-1500)/5)%256,math.floor((d.finish-1500)/5)%256,d.logic,d.linked};return q end
local function adjustmentPayload(i,d)local q={i-1,d.func,d.ena,math.floor((d.es-1500)/5)%256,math.floor((d.ee-1500)/5)%256,d.aux,math.floor((d.r1s-1500)/5)%256,math.floor((d.r1e-1500)/5)%256,math.floor((d.r2s-1500)/5)%256,math.floor((d.r2e-1500)/5)%256};rf2.mspHelper.writeU16(q,d.min<0 and d.min+65536 or d.min);rf2.mspHelper.writeU16(q,d.max<0 and d.max+65536 or d.max);q[#q+1]=d.step;return q end
local function writeModesChanged()local n=0;local keys={'id','aux','start','finish','logic','linked'};for i,d in ipairs(modes)do if recordChanged(d,modesOriginal[i],keys)then n=n+1;rf2.mspQueue:add({command=35,payload=modePayload(i,d)})end end;return n end
local function writeAdjustChanged()local n=0;local keys={'func','ena','es','ee','aux','r1s','r1e','r2s','r2e','min','max','step'};for i,d in ipairs(adjusts)do if recordChanged(d,adjustsOriginal[i],keys)then n=n+1;rf2.mspQueue:add({command=53,payload=adjustmentPayload(i,d)})end end;return n end
