local function rateShown(i)local d=rateData and rateData[i];if not d or d.value==nil then return 0 end;return d.scale and d.value/d.scale or d.value end
local function rateTypeName()local q=rateData and rateData.rates_type;return q and q.table and(q.table[q.value]or tostring(q.value))or'READ...'end
local function rateCalc(axis,x)
 if not rateData then return 0 end;local base=(axis-1)*3;local rcRate=rateShown(base);local expo=rateShown(base+1);local rate=rateShown(base+2);local t=rateData.rates_type.value or 0;local a=math.abs(x);local sign=x<0 and-1 or 1;local y=x
 if t==1 then if rcRate>2 then rcRate=rcRate+(rcRate-2)*14.54 end;if expo>0 then y=x*a*a*expo+x*(1-expo)end;local f=1/math.max(.01,1-a*rate);y=200*rcRate*y*f
 elseif t==2 then y=(1+.01*expo*(x*x-1))*x;y=y*(rcRate+math.abs(y)*rcRate*rate*.01)
 elseif t==3 then local den=math.max(.01,1-a*rate);y=((x*x*x)*expo+x*(1-expo))*(rcRate/10);y=2000*y/den
 elseif t==4 then local ef=a*((x^5)*expo+x*(1-expo));y=x*rcRate+math.max(0,rate-rcRate)*ef
 elseif t==5 then rcRate=rcRate*200;rate=math.max(rate,rcRate);local se=((rate/rcRate)-1)/(rate/rcRate);local c=a^3*expo+a*(1-expo);y=x*rcRate/math.max(.01,1-c*se)
 elseif t==6 then local shape=rate/16+2;local ef=x*(1-expo/100)+sign*(a^shape)*(expo/100);y=rcRate*ef
 else y=x*500 end;return y
end
