local function modeActive(name)local id=nil;for _,md in ipairs(modeDefs)do if md.name==name then id=md.id break end end;if id==nil then return false end;local any=false;local all=true;local count=0;local hasAnd=false;for _,d in ipairs(modes)do if d.id==id and d.finish>d.start then count=count+1;local rv=modeRc[(d.aux or 0)+6];local inside=rv and rv>=d.start and rv<=d.finish or false;if d.logic==1 then hasAnd=true;all=all and inside else any=any or inside end end end;if count==0 then return false end;return any or(hasAnd and all)end
