function M.rangeTouch(i,q,begin)if i>=1000 then local code=i-1000;local slot=math.floor(code/10);local which=code%10;local d=adjusts[slot];if not d then return end;local fa,fb=which==1 and'es'or(which==2 and'r1s'or'r2s'),which==1 and'ee'or(which==2 and'r1e'or'r2e');local v=math.floor((900+q*1200)/5+.5)*5;if begin then if math.abs(v-d[fa])<=35 then rangeDragMode=fa elseif math.abs(v-d[fb])<=35 then rangeDragMode=fb elseif v>d[fa]and v<d[fb]then rangeDragMode='adjmove';rangeDragStart={v=v,s=d[fa],e=d[fb],a=fa,b=fb}else rangeDragMode=math.abs(v-d[fa])<math.abs(v-d[fb])and fa or fb end end;if rangeDragMode=='adjmove'and rangeDragStart then local delta=v-rangeDragStart.v;delta=math.max(900-rangeDragStart.s,math.min(2100-rangeDragStart.e,delta));d[rangeDragStart.a]=rangeDragStart.s+delta;d[rangeDragStart.b]=rangeDragStart.e+delta elseif rangeDragMode==fa then d[fa]=math.min(v,d[fb])else d[fb]=math.max(v,d[fa])end;adjustsDirty=true;state='ADJUSTMENTS CHANGED / PRESS SAVE';return end;local d=modes[i];if not d then return end;local v=math.floor((900+q*1200)/5+.5)*5;if begin then if math.abs(v-d.start)<=35 then rangeDragMode='start'elseif math.abs(v-d.finish)<=35 then rangeDragMode='finish'elseif v>d.start and v<d.finish then rangeDragMode='move';rangeDragStart={v=v,s=d.start,e=d.finish}else rangeDragMode=math.abs(v-d.start)<math.abs(v-d.finish)and'start'or'finish'end end;if rangeDragMode=='move'and rangeDragStart then local delta=v-rangeDragStart.v;delta=math.max(900-rangeDragStart.s,math.min(2100-rangeDragStart.e,delta));d.start=rangeDragStart.s+delta;d.finish=rangeDragStart.e+delta elseif rangeDragMode=='start'then d.start=math.min(v,d.finish)else d.finish=math.max(v,d.start)end;modesDirty=true;state='MODES CHANGED / PRESS SAVE';build()end
