lseif e==EVT_VIRTUAL_PREV then dynamicCell=(dynamicCell-2)%15+1;return 0 elseif e==EVT_VIRTUAL_ENTER then local q=rateData and rateData[idx];if q then ui.numberDial('rate:'..idx,q.value or 0,q.min or 0,q.max or 65535,q.scale)end;return 0 end;return e elseif kind=='rates'and rateView=='table'then if e==EVT_VIRTUAL_NEXT then rateCell=rateCell%12+1;return 0 elseif e==EVT_VIRTUAL_PREV then rateCell=(rateCell-2)%12+1;return 0 elseif e==EVT_VIRTUAL_ENTER then local idx=rateCell-1;local q=rateData and rateData[idx];if q then ui.numberDial('rate:'..idx,q.value or 0,q.min or 0,q.max or 255,q.scale)end;return 0 end;return e elseif kind=='rates'and rateView=='curve'then return e elseif kind=='profiles'and gainView then if e==EVT_VIRTUAL_NEXT then gainSel=gainSel%15+1;return 0 elseif e==EVT_VIRTUAL_PREV then gainSel=(gainSel-2)%15+1;return 0 elseif e==EVT_VIRTUAL_ENTER then local idx=gainMap[gainSel];local q=pTune[idx];if q then ui.numberDial('pt:'..idx,q.value or 0,q.min or 0,q.max or 1000,q.scale)end;return 0 end;return e end;if e==EVT_VIRTUAL_NEXT then sel=sel%math.max(1,#rows)+1;return 0 elseif e==EVT_VIRTUAL_PREV then sel=(sel-2)%math.max(1,#rows)+1;return 0 elseif e==EVT_VIRTUAL_ENTER then M.activate({op='row',index=sel});return 0 end;return e end
function M.live()local now=getTime and getTime()or 0;if kind=='modes'or kind=='adjustments'then if busy or modeRcBusy or adjRcBusy or now-modeRcAt<20 or not rf2.mspQueue:isProcessed()then return end;modeRcAt=now;modeRcBusy=true;rf2.mspQueue:add({command=105,processReply=function(_,b)b.offset=1;local q={};local n=math.min(16,math.floor(#b/2));for i=1,n do q[i]=u16(b)end;for i=n+1,16 do q[i]=1500 end;modeRc=q;adjRc=q;modeRcBusy=false;adjRcBusy=false;state='AUX LIVE / '..n..' CHANNELS'end,errorHandler=function()modeRcBusy=false;adjRcBusy=false;state='AUX LIVE READ ERROR'end});return elseif kind=='rates'then if busy or not rf2.mspQueue:isProcessed()then return end;if now-rprof.last>=20 then rprof.last=now;pApis.status=pApis.status or rf2.useApi('mspStatus');pApis.status.getStatus(function(_,x)local v=x.rateProfile or 0;if v~=rprof.current then rprof.current=v;busy=true;state='RATE PROFILE #'..(v+1)..' DETECTED';readRates()end end,nil)end;return elseif kind=='profiles'then if busy or now-prof.last<20 or not rf2.mspQueue:isProcessed()then return end;prof.last=now;pApis.status.getStatus(function(_,x)local v=x.profile or 0;if v~=prof.current then prof.current=v;busy=true;state='PROFILE #'..(v+1)..' DETECTED';readProfiles()end end,nil);return end;if kind~='sensors'or busy then return end;local now=getTime and getTime()or 0;if now-lastLive<10 or not rf2.mspQueue:isProcessed()then return end;lastLive=now;busy=true;rf2.mspQueue:add({command=102,processReply=function(_,b)b.offset=1;local n={'Acc X','Acc Y','Acc Z','Gyro X','Gyro Y','Gyro Z','Mag X','Mag Y','Mag Z'};for i=1,9 do local v=u16(b);if v>=32768 then v=v-65536 end;sensor[n[i]]=v end;scopePush();busy=false end,errorHandler=function()busy=false end});rf2.mspQueue:add({command=108,processReply=function(_,b)b.offset=1;local r=u16(b);if r>=32768 then r=r-65536 end;local p=u16(b);if p>=32768 then p=p-65536 end;local y=u16(b);if y>=32768 then y=y-65536 end;sensor['Roll']=r/10;sensor['Pitch']=p/10;sensor['Yaw']=y;scopePush()end